CREATE TYPE "FriendRequestStatus" AS ENUM ('PENDING', 'ACCEPTED', 'REJECTED');
ALTER TABLE "Profile" ADD COLUMN "friendsVisible" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "Profile" ADD COLUMN "activityVisible" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "Profile" ADD COLUMN "messagePolicy" TEXT NOT NULL DEFAULT 'FRIENDS';
CREATE TABLE "Friendship" ("id" TEXT NOT NULL, "userAId" TEXT NOT NULL, "userBId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Friendship_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FriendRequest" ("id" TEXT NOT NULL, "senderId" TEXT NOT NULL, "receiverId" TEXT NOT NULL, "status" "FriendRequestStatus" NOT NULL DEFAULT 'PENDING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "FriendRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BlockedUser" ("id" TEXT NOT NULL, "blockerId" TEXT NOT NULL, "blockedId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "BlockedUser_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Message" ("id" TEXT NOT NULL, "senderId" TEXT NOT NULL, "recipientId" TEXT NOT NULL, "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "readAt" TIMESTAMP(3), CONSTRAINT "Message_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ActivityFeed" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "payload" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ActivityFeed_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PlayerRating" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "rating" INTEGER NOT NULL DEFAULT 1000, "wins" INTEGER NOT NULL DEFAULT 0, "losses" INTEGER NOT NULL DEFAULT 0, "season" TEXT NOT NULL DEFAULT '2026-S1', "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PlayerRating_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MatchHistory" ("id" TEXT NOT NULL, "duelId" TEXT, "userId" TEXT NOT NULL, "opponentId" TEXT NOT NULL, "result" TEXT NOT NULL, "ratingBefore" INTEGER NOT NULL, "ratingAfter" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MatchHistory_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Friendship_userAId_userBId_key" ON "Friendship"("userAId", "userBId");
CREATE INDEX "Friendship_userAId_createdAt_idx" ON "Friendship"("userAId", "createdAt"); CREATE INDEX "Friendship_userBId_createdAt_idx" ON "Friendship"("userBId", "createdAt");
CREATE UNIQUE INDEX "FriendRequest_senderId_receiverId_key" ON "FriendRequest"("senderId", "receiverId"); CREATE INDEX "FriendRequest_receiverId_status_createdAt_idx" ON "FriendRequest"("receiverId", "status", "createdAt"); CREATE INDEX "FriendRequest_senderId_status_createdAt_idx" ON "FriendRequest"("senderId", "status", "createdAt");
CREATE UNIQUE INDEX "BlockedUser_blockerId_blockedId_key" ON "BlockedUser"("blockerId", "blockedId"); CREATE INDEX "BlockedUser_blockedId_idx" ON "BlockedUser"("blockedId");
CREATE INDEX "Message_senderId_recipientId_createdAt_idx" ON "Message"("senderId", "recipientId", "createdAt"); CREATE INDEX "Message_recipientId_readAt_createdAt_idx" ON "Message"("recipientId", "readAt", "createdAt");
CREATE INDEX "ActivityFeed_userId_createdAt_idx" ON "ActivityFeed"("userId", "createdAt"); CREATE INDEX "ActivityFeed_eventType_createdAt_idx" ON "ActivityFeed"("eventType", "createdAt");
CREATE UNIQUE INDEX "PlayerRating_userId_key" ON "PlayerRating"("userId"); CREATE INDEX "PlayerRating_season_rating_idx" ON "PlayerRating"("season", "rating");
CREATE INDEX "MatchHistory_userId_createdAt_idx" ON "MatchHistory"("userId", "createdAt"); CREATE INDEX "MatchHistory_opponentId_createdAt_idx" ON "MatchHistory"("opponentId", "createdAt");
ALTER TABLE "Friendship" ADD CONSTRAINT "Friendship_userAId_fkey" FOREIGN KEY ("userAId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Friendship" ADD CONSTRAINT "Friendship_userBId_fkey" FOREIGN KEY ("userBId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FriendRequest" ADD CONSTRAINT "FriendRequest_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "FriendRequest" ADD CONSTRAINT "FriendRequest_receiverId_fkey" FOREIGN KEY ("receiverId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BlockedUser" ADD CONSTRAINT "BlockedUser_blockerId_fkey" FOREIGN KEY ("blockerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "BlockedUser" ADD CONSTRAINT "BlockedUser_blockedId_fkey" FOREIGN KEY ("blockedId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Message" ADD CONSTRAINT "Message_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Message" ADD CONSTRAINT "Message_recipientId_fkey" FOREIGN KEY ("recipientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ActivityFeed" ADD CONSTRAINT "ActivityFeed_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PlayerRating" ADD CONSTRAINT "PlayerRating_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "MatchHistory" ADD CONSTRAINT "MatchHistory_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;